You have a shared ARM template saved as azuredeploy.json that the platform team deploys with New-AzResourceGroupDeployment against a resource group that already exists. The file creates a Linux virtual machine, its public IP address and a key vault, and the operators pick the settings each time in the portal deployment form. The current file is shown below, and five revisions to it are still outstanding. Which revision belongs with each outstanding requirement?

`{
  "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
  "contentVersion": "1.0.0.0",
  "parameters": {
    "vmName": {
      "type": "string"
    },
    "vmSize": {
      "type": "string"
    },
    "location": {
      "type": "string"
    },
    "diskSizeGb": {
      "type": "int"
    },
    "adminPassword": {
      "type": "string"
    }
  },
  "resources": [
    {
      "type": "Microsoft.Network/publicIPAddresses",
      "apiVersion": "2023-09-01",
      "name": "[concat(parameters('vmName'), '-pip')]",
      "location": "[parameters('location')]",
      "sku": { "name": "Standard" },
      "properties": { "publicIPAllocationMethod": "Static" }
    },
    {
      "type": "Microsoft.Compute/virtualMachines",
      "apiVersion": "2023-09-01",
      "name": "[parameters('vmName')]",
      "location": "[parameters('location')]",
      "properties": {
        "hardwareProfile": {
          "vmSize": "[parameters('vmSize')]",
          "storageProfile": {
            "osDisk": {
              "diskSizeGB": "[parameters('diskSizeGb')]",
              "managedDisk": { "storageAccountType": "Premium_LRS" }
            }
          }
        },
        "osProfile": {
          "computerName": "[parameters('vmName')]",
          "adminUsername": "azureuser",
          "adminPassword": "[parameters('adminPassword')]",
          "linuxConfiguration": { "disablePasswordAuthentication": false }
        },
        "storageProfile": {
          "imageReference": {
            "publisher": "Canonical",
            "offer": "0001-com-ubuntu-server-jammy",
            "sku": "22_04-lts-gen2",
            "version": "latest"
          }
        }
      }
    },
    {
      "type": "Microsoft.KeyVault/vaults",
      "apiVersion": "2023-07-01",
      "name": "[concat(parameters('vmName'), '-kv')]",
      "location": "[parameters('location')]",
      "properties": {
        "sku": { "family": "A", "name": "standard" },
        "tenantId": "[subscription().tenantId]",
        "enableRbacAuthorization": true
      }
    }
  ]
}`

